'use strict';
// EÜR values come exclusively from the server's integer-cent calculation.
navItems.splice(navItems.findIndex(n=>n[0]==='chat'),0,['euer','EÜR vorbereiten','check']);
for(const id of ['euer-allocation-form','euer-entry-form','euer-ai-form','euer-check-form'])draftable.add(id);
const euerTabs=[['payments','Zahlungen'],['entries','Ergänzungen & AfA'],['ai','3 KI prüfen'],['check','Jahrescheck'],['report','Auswertung']];
const euerStatus={open:'Zuordnung offen',stale:'Erneut prüfen',confirmed:'Bestätigt',excluded:'Privat / Eigenübertrag'};
const euerValue=c=>`${c<0?'-':''}${Math.floor(Math.abs(c)/100)},${String(Math.abs(c)%100).padStart(2,'0')}`;
const euerHidden=(key,value)=>`<input type="hidden" name="${key}" value="${esc(value)}">`;
function euerFooter(label='Zuordnung bestätigen'){return `<div class="modal-footer"><span class="save-state small" role="status">Eingaben werden als Entwurf gesichert.</span>${button('Schließen','close-modal','','ghost')}<button class="btn primary" type="submit">${label}</button></div>`;}
function euerView(){
 const r=app.euer;
 if(!r||r.year!==app.year)return head('EÜR vorbereiten.','Zahlungen, Ergänzungen und Beleggrundlagen zusammenführen.')+'<section class="panel panel-body" role="status">Arbeitsstand wird geladen …</section>';
 const tab=app.euerTab||'payments',pending=r.counts.open+r.counts.stale;
 return `<div class="euer-workspace">${head('Deine EÜR '+r.year+'.','Vom einzelnen Beleg zum nachvollziehbaren Arbeitsentwurf.',button('Neu laden','euer-refresh','right','ghost small'))}
 ${!r.supported?'<div class="answer-warning">Die Formularzuordnung ist für 2025 eingerichtet. Für dieses Arbeitsjahr bleibt die EÜR-Bearbeitung gesperrt.</div>':''}
 <section class="panel euer-intro"><div><span class="eyebrow">ARBEITSSTAND</span><h2>${pending?`${pending} Zahlungen zuordnen`:'Zuordnungen durchgesehen'}</h2><p>${r.counts.confirmed} bestätigt · ${r.counts.excluded} nach deiner Einordnung privat oder Eigenübertrag. ${r.open.length} offene Jahres- und Zuordnungspunkte.</p></div><div class="euer-intro-action">${button('Steuerstatus '+r.year,'startcheck','settings','small')}<span class="small muted">Beträge entstehen aus deinen bestätigten Angaben.</span></div></section>
 ${draftBanner()}<nav class="euer-tabs" aria-label="EÜR-Arbeitsschritte">${euerTabs.map(([id,label])=>`<button class="${tab===id?'selected':''}" data-action="euer-tab" data-tab="${id}"${tab===id?' aria-current="page"':''}>${esc(label)}</button>`).join('')}</nav>
 <div id="euer-content">${({payments:euerPayments,entries:euerEntries,ai:euerAIView,check:euerCheck,report:euerReport})[tab](r)}</div></div>`;
}
function euerPayments(r){
 const filter=app.euerFilter||'open',query=(app.euerSearch||'').toLocaleLowerCase('de');
 const rows=r.rows.filter(x=>(filter==='all'||filter==='open'&&['open','stale'].includes(x.status)||filter==='confirmed'&&x.status==='confirmed')&&(!query||`${x.partner} ${x.title} ${x.paid_on}`.toLocaleLowerCase('de').includes(query)));
 return `<section class="panel"><div class="panel-header"><div><h2>Zahlungen zuordnen</h2><p class="small muted">Die Bankbeträge bleiben erhalten. Hier legst du den steuerlichen Ansatz fest.</p></div></div><div class="euer-tools"><div class="scope-tabs">${[['open',`Offen (${r.counts.open+r.counts.stale})`],['confirmed',`Bestätigt (${r.counts.confirmed})`],['all',`Alle (${r.rows.length})`]].map(([id,label])=>button(label,'euer-filter','',filter===id?'selected':'',`data-filter="${id}"`)).join('')}</div><label class="euer-search">Suchen<input type="search" id="euer-search" value="${esc(app.euerSearch||'')}" placeholder="Empfänger, Text, Datum"></label></div><div id="euer-payment-list">${euerPaymentList(rows,r)}</div><div class="panel-body"><p class="small muted">Eine fehlende Belegverknüpfung bedeutet nicht, dass du keinen Beleg besitzt. Verknüpfe ihn unter „Zahlung / Belege“. Jahreswechsel-Korrekturen bitte mit Begründung über Ergänzungen erfassen; keine Zahlung doppelt ansetzen.</p></div></section>`;
}
function euerPaymentList(rows,r){return rows.length?`<div class="euer-table-wrap"><table class="euer-table"><thead><tr><th>Zahlung</th><th>Einordnung / Ansatz</th><th class="numeric">Brutto</th><th>Bearbeiten</th></tr></thead><tbody>${rows.map(t=>{const a=t.allocation,docs=t.document_ids.map(id=>app.data.documents.find(d=>d.id===id)).filter(Boolean),p=a&&r.positions_catalog.find(x=>x.code===a.position);return `<tr><td><small>${fmtDate(t.paid_on)} · ${esc(scopeNames[t.scope]||t.scope)}</small><strong>${esc(t.partner)}</strong><span class="euer-description">${esc(t.title)}</span></td><td><span class="tag ${['open','stale'].includes(t.status)?'amber':t.status==='confirmed'?'green':''}">${euerStatus[t.status]}</span>${a?`<p class="small">${p?`Z. ${p.code} · ${esc(p.label)}`:a.position==='asset'?'Anschaffung → Anlageverzeichnis':'Ausgeschlossen'}</p>`:''}<small class="muted">${docs.filter(d=>d.kind!=='Kontoauszug').length} gesonderte Belege verknüpft${t.bank_import_id?' · Banknachweis':''}</small></td><td class="numeric">${t.direction==='income'?'+':'−'} ${money(t.amount_cents)}</td><td><div class="actions">${r.supported?button('Zuordnen','euer-allocation','edit','small',`data-id="${t.id}"`):''}${button('Zahlung / Belege','euer-payment','file','ghost small',`data-id="${t.id}"`)}</div></td></tr>`;}).join('')}</tbody></table></div>`:'<div class="euer-empty"><span>✓</span><h3>Keine Zahlungen in diesem Filter.</h3><p>Weitere Schritte findest du unter Ergänzungen und Jahrescheck.</p></div>';}
function euerAllocation(id,proposal=null){
 const r=app.euer,t=r.rows.find(x=>x.id===id);if(!t)return toast('Zahlung nicht mehr in diesem Jahr aktiv.',true);
 const a=t.allocation||{},position=proposal?.position??a.position??'',vat=proposal?proposal.vat??'':a.vat_cents===undefined?'':euerValue(a.vat_cents),note=proposal?`${proposal.note}${proposal.question?'\nOffen: '+proposal.question:''}`:a.note||'';
 const docs=t.document_ids.map(id=>app.data.documents.find(d=>d.id===id)).filter(Boolean);
 showModal('EÜR-Zuordnung · '+t.partner,`<form id="euer-allocation-form" data-id="${id}" data-year="${r.year}"><div class="modal-body"><div class="form-result" role="alert"></div>${euerHidden('tx_id',id)}${euerHidden('year',r.year)}${euerHidden('source_hash',t.source_hash)}${euerHidden('revision',t.revision)}<div class="euer-source"><strong>${t.direction==='income'?'Zahlungseingang':'Zahlungsausgang'} · ${money(t.amount_cents)}</strong><p>${fmtDate(t.paid_on)} · ${esc(t.title)}</p><p class="small">Gespeicherter Bereich: ${esc(scopeNames[t.scope])}. Eine abweichende EÜR-Einordnung bitte begründen.</p></div>${proposal?'<p class="answer-warning">KI-Vorschlag zur Prüfung. Position und Steuerbetrag können falsch oder unvollständig sein. Erst deine Bestätigung übernimmt die Zuordnung.</p>':''}${t.stale?'<p class="answer-warning">Die zugrunde liegenden Angaben wurden geändert. Bitte alle Felder neu prüfen.</p>':''}
 ${select('EÜR-Position 2025','position',[['','Bitte auswählen'],...r.positions_catalog.filter(p=>r.bank_positions.includes(p.code)).map(p=>[p.code,`${p.kind==='income'?'Einnahme':'Ausgabe'} · Z. ${p.code} · ${p.label}`]),['asset','Anschaffung · netto nicht sofort abziehen'],['exclude','Nicht in dieser EÜR ansetzen · begründen']],position)}
 <div class="field-row">${field('Betrieblicher Anteil der Zahlung (%)','business_percent',a.business_percent??t.business_percent??(t.scope==='business'?100:''),'number','required min="0" max="100" step="1"')}${field('Abziehbarer Anteil des Nettobetrags (%)','deductible_percent',position==='63'?70:a.deductible_percent??100,'number','required min="0" max="100" step="1"')}</div>
 ${field('Im betrieblichen Zahlungsanteil: abziehbare / vereinnahmte USt (€)','vat',vat,'text','required inputmode="decimal" placeholder="Ungeklärt: erst prüfen. Ohne USt: 0,00"')}<p class="small muted">Trage nur den Steuerbetrag des betrieblichen Anteils ein. Die abziehbare Vorsteuer wird separat angesetzt. Bei Bewirtung kann der Vorsteuerabzug vom 70-%-Abzug der Nettokosten abweichen. Reverse Charge und innergemeinschaftliche Erwerbe gesondert prüfen.</p>
 ${textarea('Beleggrundlage und Begründung','note',note,'required maxlength="4000" placeholder="Rechnung / Fundstelle, betrieblicher Zweck, Anteil und steuerliche Behandlung …"')}
 <p class="small muted">Eingänge auf Ausgabenpositionen mindern die Kosten; Ausgänge auf Einnahmenpositionen mindern die Erlöse. Verwende dies nur für begründete Erstattungen/Stornos. Anschaffungen anschließend im Anlageverzeichnis ergänzen.</p>
 <details class="source-details"><summary>Verknüpfte Unterlagen (${docs.length})</summary>${docs.map(d=>button(esc(d.title),'open-document','file','small',`data-id="${d.id}"`)).join('')||'<p>Hier ist noch kein Dokument verknüpft.</p>'}</details>
 <label class="check"><input type="checkbox" name="confirmed" required>Ich habe Position, Anteil, Steuerbetrag und Beleggrundlage geprüft.</label></div>${euerFooter()}</form>`);
}
function euerEntries(r){return `<section class="panel"><div class="panel-header"><div><h2>Werte ohne neue Bankzahlung</h2><p class="small muted">Zum Beispiel Tagespauschale, Sachentnahmen und begründete Korrekturen.</p></div>${r.supported?button('Ergänzung','euer-new-entry','plus','primary small','data-kind="supplement"'):''}</div><div class="panel-body"><p class="small muted">Nur den bereits ermittelten steuerlichen Betrag eintragen. Quelle, Berechnung und Bezug auf vorhandene Zahlungen festhalten, damit kein doppelter Ansatz entsteht.</p>${euerEntryList(r,'supplement')}</div></section><section class="panel section-gap"><div class="panel-header"><div><h2>Anlageverzeichnis · Jahres-AfA</h2><p class="small muted">Jahreswerte anhand des tatsächlichen Anlagenachweises erfassen.</p></div>${r.supported?button('Anlage ergänzen','euer-new-entry','plus','small','data-kind="asset"'):''}</div><div class="panel-body"><p class="small muted">Die AfA wird hier aus deinem geprüften Jahresbetrag übernommen. Ein Betrag aus der EÜR 2024 ist kein Nachweis der AfA 2025. Anfangsbuchwert + Zugänge − AfA − Abgänge ergibt den Endbuchwert.</p>${euerEntryList(r,'asset')}</div></section>`;}
function euerEntryList(r,kind){const ee=r.entries.filter(x=>x.kind===kind);return ee.length?`<div class="euer-entry-list">${ee.map(e=>`<article><div><strong>${esc(e.title)}</strong><p class="small muted">Z. ${e.position} · ${esc(e.note)}</p>${e.kind==='asset'?`<p class="small">Anfang ${money(e.opening_cents)} + Zugang ${money(e.additions_cents)} − AfA ${money(e.depreciation_cents)} − Abgang ${money(e.disposals_cents)} = Ende ${money(e.closing_cents)}</p>`:''}${e.stale?'<p class="answer-warning">Anschaffung, Beleggrundlage oder Steuerprofil geändert. Der Ansatz bleibt bis zur erneuten Bestätigung aus der Berechnung.</p>':''}</div><strong>${money(e.amount_cents)}</strong>${button('Bearbeiten','euer-edit-entry','edit','small',`data-id="${e.id}"`)}</article>`).join('')}</div>`:'<p class="euer-quiet">Noch keine Einträge. Wenn nichts anzusetzen ist, halte die Prüfung später im Jahrescheck fest.</p>';}
function euerEntryForm(id=null,kind='supplement'){
 const r=app.euer,e=id?r.entries.find(x=>x.id===id):{};if(id&&!e)return toast('Eintrag nicht mehr aktiv.',true);kind=e.kind||kind;
 showModal(kind==='asset'?'Anlage und AfA '+r.year:'Ergänzung '+r.year,`<form id="euer-entry-form" data-id="${id||''}" data-year="${r.year}" data-draft-key="euer-entry-form:${id||kind}:${r.year}"><div class="modal-body"><div class="form-result" role="alert"></div>${euerHidden('year',r.year)}${euerHidden('kind',kind)}${euerHidden('revision',e.revision||'')}${field('Bezeichnung','title',e.title||'','text','required maxlength="200"')}
 ${select('EÜR-Position','position',[['','Bitte auswählen'],...r.positions_catalog.filter(p=>kind==='asset'?['31','32','33'].includes(p.code):!['31','32','33'].includes(p.code)).map(p=>[p.code,`Z. ${p.code} · ${p.label}`])],e.position||'')}
 ${kind==='asset'?`${field('Anschaffungsdatum','acquired_on',e.acquired_on||'','date','required')}<div class="field-row">${field('Buchwert am Jahresanfang (€)','opening',e.opening_cents===undefined?'':euerValue(e.opening_cents),'text','required inputmode="decimal"')}${field('Zugänge dieses Jahres (€)','additions',e.additions_cents===undefined?'':euerValue(e.additions_cents),'text','required inputmode="decimal"')}</div><div class="field-row">${field('Geprüfte AfA dieses Jahres (€)','depreciation',e.depreciation_cents===undefined?'':euerValue(e.depreciation_cents),'text','required inputmode="decimal"')}${field('Buchwert-Abgänge (€)','disposals',e.disposals_cents===undefined?'':euerValue(e.disposals_cents),'text','required inputmode="decimal"')}</div>${select('Zugehörige Anschaffungszahlung','tx_id',[['','Vorjahresanlage / separat dokumentiert'],...r.rows.filter(t=>t.status==='confirmed'&&t.allocation?.position==='asset').map(t=>[t.id,`${fmtDate(t.paid_on)} · ${t.partner} · ${money(t.amount_cents)}`])],e.tx_id||'')}<p class="small muted">Buchwerte und AfA des betrieblichen Anlagevermögens verwenden, ohne abziehbare Vorsteuer. Abgänge werden hier im Buchwert geführt; einen abziehbaren Restbuchwert gegebenenfalls zusätzlich mit Z. 38 dokumentieren. Keine automatische Nutzungsdauer oder AfA-Methode.</p>`:field('Steuerlich anzusetzender Betrag (€; Minderung mit Minus)','amount',e.amount_cents===undefined?'':euerValue(e.amount_cents),'text','required inputmode="decimal"')}
 ${select('Beleggrundlage verknüpfen (optional)','source_id',[['','Berechnung / Quelle nur in der Notiz'],...app.data.documents.map(d=>[d.id,`${d.year} · ${d.title}`])],e.source_id||'')}${textarea('Quelle, Berechnung und Abgrenzung zu anderen Ansätzen','note',e.note||'','required maxlength="4000" placeholder="Anlage / Fundstelle, Nutzungsdauer und Methode bzw. Tage/Wertnachweis, steuerliche Voraussetzungen …"')}<label class="check"><input type="checkbox" name="confirmed" required>Ich habe den Ansatz und die Berechnung für dieses Jahr geprüft.</label>${id?button('Eintrag entfernen','euer-archive-entry','trash','ghost danger small',`data-id="${id}"`):''}</div>${euerFooter('Eintrag speichern')}</form>`);
}
function euerCheck(r){return `<section class="panel"><div class="panel-header"><h2>Das ganze Jahr durchsehen</h2></div><form id="euer-check-form" data-year="${r.year}" data-draft-key="euer-check-form:${r.year}" class="panel-body"><div class="form-result" role="alert"></div>${euerHidden('year',r.year)}${euerHidden('fingerprint',r.fingerprint)}<p class="small muted">Diese Bestätigungen beziehen sich auf den aktuellen Datenstand. Nach Änderungen werden sie erneut fällig. Einzelzuordnungen ersetzen diese Prüfung nicht.</p>${Object.entries(r.check_labels).map(([key,label])=>`<label class="check euer-check-item"><input type="checkbox" name="${key}"${r.checks[key]?' checked':''}>${esc(label)}</label>`).join('')}<div class="actions section-gap">${r.supported?'<button class="btn primary" type="submit">Jahrescheck speichern</button>':''}<span class="save-state small" role="status"></span></div></form></section><section class="panel section-gap"><div class="panel-header"><h2>Offene Punkte (${r.open.length})</h2></div><div class="panel-body">${euerOpen(r)}</div></section>`;}
function euerOpen(r){return r.open.length?`<ul class="euer-open-list">${r.open.map(x=>`<li>${esc(x.text)}${x.kind==='transaction'?button('Öffnen','euer-allocation','','small',`data-id="${x.id}"`):x.kind==='entry'?button('Öffnen','euer-edit-entry','','small',`data-id="${x.id}"`):''}</li>`).join('')}</ul>`:'<p>Die hier vorgesehenen Prüfungen sind bestätigt. Weitere steuerliche Gewinnkorrekturen und die Abgabe bleiben gesonderte Schritte.</p>';}
function euerReport(r){return `<div class="euer-print-report"><div class="euer-report-heading"><span class="eyebrow">EÜR ${r.year} · ARBEITSENTWURF</span><h2>${r.open.length?'Zwischenstand aus bestätigten Positionen':'Bestätigte Positionen zusammengefasst'}</h2><p class="small muted">${esc(r.limitation)}</p></div><div class="euer-totals"><div><span>Einnahmen</span><strong>${money(r.income_cents)}</strong></div><div><span>Ausgaben</span><strong>${money(r.expense_cents)}</strong></div><div><span>Differenz vor weiteren Gewinnkorrekturen</span><strong>${money(r.balance_cents)}</strong></div></div><div class="actions euer-no-print section-gap">${button('CSV mit Einzelansätzen','euer-export','download','primary small')}${button('Drucken / als PDF speichern','euer-print','file','small')}<a href="${esc(r.source_url)}" class="btn ghost small" target="_blank" rel="noreferrer">Amtliche Anleitung 2025 ↗</a></div><section class="panel section-gap"><div class="panel-header"><h2>Ansätze nach EÜR-Position</h2><span class="tag">${r.open.length} Punkte offen</span></div><div class="euer-table-wrap"><table class="euer-table"><thead><tr><th>Zeile 2025</th><th>Position</th><th class="numeric">Betrag</th></tr></thead><tbody>${r.positions.map(p=>`<tr><td>${p.code}</td><td>${esc(p.label)}</td><td class="numeric">${money(p.amount_cents)}</td></tr>`).join('')||'<tr><td colspan="3">Noch keine bestätigten Ansätze. Fehlende Angaben sind keine bestätigten Nullwerte.</td></tr>'}</tbody></table></div></section><section class="panel section-gap"><div class="panel-header"><h2>Einzelansätze mit Herkunft</h2></div><div class="euer-table-wrap"><table class="euer-table"><thead><tr><th>Ansatz / Quelle</th><th>Begründung</th><th>Zeile</th><th class="numeric">Betrag</th></tr></thead><tbody>${r.details.map(x=>`<tr><td>${esc(x.label)}<small>${esc(x.source)}</small></td><td>${esc(x.note)}</td><td>${x.position}</td><td class="numeric">${money(x.amount_cents)}</td></tr>`).join('')}</tbody></table></div></section>${r.nondeductible.length?`<section class="panel section-gap"><div class="panel-header"><h2>Nicht abziehbarer Nettoteil</h2></div><div class="panel-body"><p class="small muted">Nicht in den Betriebsausgaben enthalten; gegebenenfalls getrennte Formularfelder beachten.</p>${r.nondeductible.map(x=>`<p>Z. ${x.position} · ${esc(x.label)} · ${money(x.amount_cents)}</p>`).join('')}</div></section>`:''}<section class="panel section-gap"><div class="panel-header"><h2>Offene Punkte</h2></div><div class="panel-body">${euerOpen(r)}</div></section><p class="small muted section-gap">Nicht alle Formularfelder sind abgebildet. Insbesondere weitere Gewinnkorrekturen, Entnahmen/Einlagen, Anlage SZ und besondere Kfz-Sachverhalte separat bearbeiten. Umsatzsteuer- und Einkommensteuererklärung werden nicht aus diesem Arbeitsentwurf berechnet.</p></div>`;}
function euerAIView(r){return `<section class="panel"><div class="panel-header"><div><h2>Unterlagen lesen und Zuordnungen vorschlagen</h2><p class="small muted">Qwen und Gemma arbeiten unabhängig. Der Koordinator vergleicht ihre Vorschläge pro Zahlung.</p></div></div><form id="euer-ai-form" data-year="${r.year}" data-draft-key="euer-ai-form:${r.year}" class="panel-body"><div class="form-result" role="alert"></div>${euerHidden('year',r.year)}${textarea('Dein vollständiger Auftrag','question',`Prüfe die betrieblichen und ungeklärten Zahlungen für die EÜR ${r.year}. Lies die verfügbaren Dokumenttexte. Schlage passende EÜR-Positionen vor. Nenne je Zahlung die belegte Umsatzsteuer oder eine konkrete Rückfrage. Übernimm keine Vorjahres-AfA ungeprüft.`, 'required maxlength="12000"')}<details class="source-details"><summary>Zusätzliche Unterlagen aus anderen Jahren mitgeben</summary><p class="small muted">Aktuelle Jahresunterlagen (außer Kontoauszügen) und verknüpfte Rechnungen werden automatisch berücksichtigt. Bis zu zehn weitere Dokumente, etwa Anlageverzeichnis 2024, auswählen.</p><label for="euer-documents">Zusätzliche Unterlagen</label><select id="euer-documents" name="document_ids" multiple size="5">${app.data.documents.map(d=>`<option value="${d.id}">${d.year} · ${esc(d.title)}</option>`).join('')}</select></details><p class="small muted">Die Leser bearbeiten den gesamten gespeicherten Dokumenttext in Abschnitten. Bilder und Scans ohne Text bleiben offen. Zahlungsvorschläge nutzen Zusammenfassungen verknüpfter oder zusätzlich ausgewählter Dokumente. Laufzeit hängt von deinen lokalen Modellen ab.</p><div class="actions section-gap">${r.supported?'<button class="btn primary" type="submit">EÜR-Prüfung starten</button>':''}<span class="save-state small" role="status">Auftrag wird als Entwurf gespeichert.</span></div></form></section><div id="euer-ai-results" class="section-gap">${euerAIResults()}</div>`;}
function euerAIResults(){const runs=app.euerRunsYear===app.year?app.euerRuns||[]:[];return runs.length?runs.map((run,i)=>`<details class="panel euer-run"${i===0?' open':''}><summary><strong>${stamp(run.created_at)} · ${{complete:'Beantwortet',error:'Unterbrochen',running:'Läuft',queued:'Startet'}[run.state]}</strong><span>${run.done} / ${run.total} Schritte</span></summary><div class="panel-body"><p class="progress-label">${['running','queued'].includes(run.state)?'<span class="spinner"></span>':''}${esc(run.progress)}</p><progress max="${run.total}" value="${run.done}" aria-label="Abgeschlossene KI-Schritte"></progress>${run.stale?'<p class="answer-warning">Daten seit dieser Prüfung geändert. Vorschläge zeigen den damaligen Stand; für neue Zuordnungen erneut prüfen.</p>':''}${run.error?`<div class="answer-warning"><strong>Fertige Schritte bleiben gespeichert.</strong><p>${esc(run.error)}</p>${!run.stale?button('Prüfung fortsetzen','euer-resume','spark','small',`data-id="${run.id}"`):''}</div>`:''}<details class="source-details"><summary>Auftrag und gelesene Textabschnitte</summary><p class="euer-question">${esc(run.question)}</p><ul>${run.coverage.map(d=>`<li>${esc(d.title)} · ${d.characters} Zeichen · Arbeiter ${d.worker}/${d.parts}, Prüfer ${d.reviewer}/${d.parts}${!d.characters?' · Kein lesbarer Text':''}<p class="small muted">${esc(d.extraction_note)}</p></li>`).join('')}</ul><p class="small muted">Gezählt werden beantwortete Textabschnitte. Das bestätigt keine vollständige visuelle Belegprüfung oder steuerliche Richtigkeit.</p>${run.document_notes.map(n=>`<p class="small"><strong>${{worker:'Arbeiter',reviewer:'Prüfer'}[n.role]} · ${esc(run.coverage.find(d=>d.id===n.document_id)?.title)} · ab Zeichen ${n.start+1}</strong><br>${esc(n.note)}${n.quote?`<br><q>${esc(n.quote)}</q>`:''}</p>`).join('')}</details><h3 class="section-gap">Vorschläge je Zahlung</h3>${run.suggestions.map(s=>`<article class="euer-suggestion"><strong>${esc(s.label)}</strong>${s.disagreement?'<p class="answer-warning">Arbeiter und Prüfer weichen bei Position oder Umsatzsteuer voneinander ab. Beide Begründungen und den Beleg prüfen.</p>':''}<div class="euer-reader-grid">${[['worker','Arbeiter'],['reviewer','Prüfer'],['coordinator','Koordinator']].map(([role,label])=>{const p=s[role];return `<div><span class="eyebrow">${label}</span>${p?`<p><strong>${p.position?`Vorschlag ${esc(p.position)}`:'Position offen'}</strong> · USt ${p.vat!==null?esc(p.vat)+' €':'offen'}</p><p>${esc(p.note)}</p>${p.question?`<p class="euer-question-open">${esc(p.question)}</p>`:''}${!run.stale?button('Im Formular prüfen','euer-proposal','edit','small',`data-run="${run.id}" data-id="${s.tx_id}" data-role="${role}"`):''}`:'<p class="small muted">Noch keine vollständige Antwort.</p>'}</div>`;}).join('')}</div></article>`).join('')||'<p class="small muted">In diesem Lauf werden nur Dokumenttexte gelesen.</p>'}</div></details>`).join(''):'<div class="euer-empty"><h3>Noch keine EÜR-Prüfung gestartet.</h3><p>Zuordnungen und Ergänzungen kannst du auch direkt ohne KI bearbeiten.</p></div>';}
async function loadEuer(){const year=app.year,revision=(app.euerLoadRevision||0)+1;app.euerLoadRevision=revision;try{const data=await api('/api/euer?year='+year);if(app.year!==year||revision!==app.euerLoadRevision)return;app.euer=data;if(app.view==='euer')$('#main').innerHTML=euerView();if(app.view==='euer'&&app.euerTab==='ai')loadEuerRuns();}catch(e){if(app.year===year&&revision===app.euerLoadRevision){toast(e.message,true);if(app.view==='euer')$('#main').innerHTML=head('EÜR konnte nicht geladen werden.',e.message,button('Erneut laden','euer-refresh'));}}}
async function loadEuerRuns(){const year=app.year,revision=(app.euerRunsRevision||0)+1;app.euerRunsRevision=revision;try{const items=await api('/api/euer/runs?year='+year);if(app.year!==year||revision!==app.euerRunsRevision)return;app.euerRuns=items;app.euerRunsYear=year;if($('#euer-ai-results')&&!$('#modal').open)$('#euer-ai-results').innerHTML=euerAIResults();clearTimeout(app.euerPoll);if(items.some(x=>['running','queued'].includes(x.state)))app.euerPoll=setTimeout(loadEuerRuns,3500);}catch(e){if(revision===app.euerRunsRevision)toast(e.message,true);}}
const euerBaseRender=render;
render=function(){if(app.view!=='euer')return euerBaseRender();app.view='overview';euerBaseRender();app.view='euer';$('#main').dataset.view='euer';$('#main').innerHTML=euerView();$('#breadcrumb-current').textContent='EÜR vorbereiten';document.querySelectorAll('#nav .nav-item').forEach(n=>{n.classList.toggle('active',n.dataset.view==='euer');if(n.dataset.view==='euer')n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});loadEuer();};
const euerBaseAction=action;
action=async function(name,el){
 if(!name.startsWith('euer-'))return euerBaseAction(name,el);
 if(name==='euer-tab'){app.euerTab=el.dataset.tab;$('#main').innerHTML=euerView();if(app.euerTab==='ai')await loadEuerRuns();return;}
 if(name==='euer-filter'){app.euerFilter=el.dataset.filter;$('#euer-content').innerHTML=euerPayments(app.euer);return;}
 if(name==='euer-refresh')return refresh();
 if(name==='euer-allocation')return euerAllocation(el.dataset.id);
 if(name==='euer-payment')return transactionForm(el.dataset.id);
 if(name==='euer-new-entry')return euerEntryForm(null,el.dataset.kind);
 if(name==='euer-edit-entry')return euerEntryForm(el.dataset.id);
 if(name==='euer-export')return download('/api/euer.csv?year='+app.year,`EUER-Arbeitsentwurf-${app.year}.csv`);
 if(name==='euer-print')return window.print();
 if(name==='euer-proposal'){const run=(app.euerRuns||[]).find(r=>r.id===el.dataset.run),p=run?.suggestions.find(s=>s.tx_id===el.dataset.id)?.[el.dataset.role];if(!run||run.stale||!p)return toast('Vorschlag nicht mehr aktuell. Prüfung neu starten.',true);return euerAllocation(el.dataset.id,p);}
 if(name==='euer-archive-entry'){const e=app.euer.entries.find(e=>e.id===el.dataset.id);if(!confirm('Diesen ergänzenden Ansatz aus dem Arbeitsentwurf entfernen? Er bleibt im Änderungsprotokoll nachvollziehbar.'))return;await api('/api/euer/entry',{id:e.id,year:app.year,revision:e.revision,archive:true});clearTimeout(app.draftTimer);await removeDraft($('#euer-entry-form'));app.suppressDraft=true;closeModal();app.suppressDraft=false;await refresh();return;}
 if(name==='euer-resume'){el.disabled=true;try{await api('/api/euer/resume',{id:el.dataset.id});await loadEuerRuns();toast('Gespeicherte EÜR-Prüfung wird fortgesetzt.');}catch(e){toast(e.message,true);}finally{el.disabled=false;}return;}
};
const euerBaseSubmit=submit;
submit=async function(form){if(!form.id.startsWith('euer-'))return euerBaseSubmit(form);const btn=$('[type="submit"]',form),result=$('.form-result',form);btn.disabled=true;form.inert=true;result.textContent='';try{clearTimeout(app.draftTimer);const payload=await collectForm(form);if(form.id==='euer-entry-form')payload.id=form.dataset.id||'';const route={'euer-allocation-form':'allocation','euer-entry-form':'entry','euer-ai-form':'start','euer-check-form':'review'}[form.id];if(route!=='start'){form.dataset.requestId=form.dataset.requestId||crypto.randomUUID().replaceAll('-','');payload.request_id=form.dataset.requestId;await queueDraft(form);}await api('/api/euer/'+route,payload);await removeDraft(form);app.suppressDraft=true;closeModal();app.suppressDraft=false;if(route==='start')app.euerTab='ai';await refresh();toast(route==='start'?'EÜR-Prüfung gestartet. Jeder fertige Schritt wird gespeichert.':'Gespeichert. Der Arbeitsentwurf wurde neu berechnet.');}catch(e){result.className='form-result form-error';result.textContent=e.message;}finally{btn.disabled=false;form.inert=false;app.suppressDraft=false;}};
const euerBaseClose=closeModal;
closeModal=function(){const form=$('#modal form');if(!app.suppressDraft&&form?.id?.startsWith('euer-')){clearTimeout(app.draftTimer);const saved=queueDraft(form);app.suppressDraft=true;euerBaseClose();app.suppressDraft=false;saved.then(async()=>{app.data=await api('/api/state');if(app.view==='euer'&&!$('#modal').open)render();}).catch(e=>toast(e.message,true));return;}return euerBaseClose();};
const euerBaseResumeDraft=resumeDraft;
resumeDraft=async function(key){if(!key.startsWith('euer-'))return euerBaseResumeDraft(key);const all=await api('/api/drafts'),saved=all.find(d=>d.key===key);if(!saved)return toast('Entwurf nicht mehr vorhanden.');const p=saved.payload;app.year=Number(p.__year)||app.year;app.view='euer';await loadEuer();if(p.__form==='euer-allocation-form')euerAllocation(p.__id);else if(p.__form==='euer-entry-form')euerEntryForm(p.__id||null,p.kind);else{app.euerTab=p.__form==='euer-ai-form'?'ai':'check';render();await loadEuer();}const form=$('#'+p.__form);if(!form)return toast('Dieser Entwurf gehört zu einem nicht mehr aktiven Datensatz.',true);for(const el of form.elements){if(!el.name||!(el.name in p))continue;if(el.type==='checkbox')el.checked=false;else if(el.tagName==='SELECT'&&el.multiple)[...el.options].forEach(o=>o.selected=(p[el.name]||[]).includes(o.value));else el.value=p[el.name];}form.dataset.draftKey=key;form.dataset.requestId=p.__request_id||'';toast('Entwurf geöffnet. Angaben vor dem Speichern erneut bestätigen.');};
document.addEventListener('input',event=>{if(event.target.id!=='euer-search')return;app.euerSearch=event.target.value;const r=app.euer,filter=app.euerFilter||'open',query=app.euerSearch.toLocaleLowerCase('de');$('#euer-payment-list').innerHTML=euerPaymentList(r.rows.filter(t=>(filter==='all'||filter==='open'&&['open','stale'].includes(t.status)||filter==='confirmed'&&t.status==='confirmed')&&`${t.partner} ${t.title} ${t.paid_on}`.toLocaleLowerCase('de').includes(query)),r);});
document.addEventListener('change',event=>{const form=event.target.closest('#euer-allocation-form');if(!form||event.target.name!=='position')return;const pos=event.target.value;if(pos==='63')form.elements.deductible_percent.value='70';if(pos==='exclude'){form.elements.business_percent.value='0';form.elements.vat.value='0,00';form.elements.deductible_percent.value='100';}form.elements.confirmed.checked=false;queueDraft(form);});
const euerChatView=chatView;chatView=function(){return euerChatView().replace('<div class="chat-layout">',`<div class="euer-chat-tip"><p><strong>Eine EÜR bearbeiten?</strong> Im EÜR-Arbeitsbereich liest du Belege, prüfst Zuordnungen und berechnest den Entwurf. Eine freie Frage bleibt hier eine freie Frage.</p>${button('EÜR vorbereiten','navigate','arrow','small','data-view="euer"')}</div><div class="chat-layout">`);};
start();
